import data from './design.json';

/// Generated by scripts/sync-design.mjs from docs/design. Do not edit
/// design.json by hand; edit the markdown and re-run the script.
export interface DesignDoc {
	slug: string;
	path: string;
	title: string;
	status: string;
	html: string;
}

// The product map leads; the rest follow in file order.
export const designDocs = [...(data as DesignDoc[])].sort((a, b) => (a.slug === 'product-map' ? -1 : b.slug === 'product-map' ? 1 : 0));
export const productMap = designDocs.find((d) => d.slug === 'product-map') ?? null;
